/* ==========================================================
 * 构思技艺 (GS) —— 「Bad Apple」
 * items.yml 里由  script: gs_bad_apple  引用；入口函数 onUse(event)
 * ----------------------------------------------------------
 * 右键：**播放一整首《Bad Apple!!!》**（红石音乐，36462 个音符 / 183.5 秒）
 *   · 曲谱来自 `server\plugins\Bad Apple!!!.nbs`，
 *     已经**离线转成下面 SG_TL 这张表**并写死在本文件里
 *     ⇒ **服务器运行时不用读 .nbs，也不需要任何额外依赖**。
 *   · **不消耗**物品（可以反复按）。
 *   · ★★ **冷却 = 本曲时长**（`SG_CD_MS = SG_LEN_MS` = 183536 毫秒 = 183.5 秒）：
 *     曲子放完的那一刻冷却正好走完 ⇒ **理论上可以无缝连播**。
 *   · 冷却中**静默忽略**（不提示）；
 *     想改成「显示还剩几秒」，把下面 SG_CD_HINT 改成 true 即可。
 *   · **无法与任何方块交互**：手持本物品右键方块时，方块的功能一律不触发
 *     （不开箱子 / 不耕田 / 不放方块 / 不点按钮…），只走本脚本的音效。
 * ----------------------------------------------------------
 * ★★ 默认只有**按的那个人自己**听得到（走 p.playSound）。
 *    想让**附近所有人都听到**，把下面 SG_OWNER_ONLY 改成 false 就行。
 * ★ 「无法交互」的实现顺序（和「麦友的酒」拦桶同一个套路）：
 *   Slimefun 在 NORMAL 优先级发 PlayerRightClickEvent（触发 onUse），
 *   我们注册在 HIGHEST → 一定在 onUse 之后才 setCancelled，
 *   所以「音效照放、方块交互被拦」，两者互不影响。
 * ----------------------------------------------------------
 * ★ 音高说明：音符盒只有 0~24 共 25 档（2 个八度），本曲跨度超过 2 个八度，
 *   所以取了**全局平移 +7**（落进范围的音最多），超出的音按八度折回。
 *   这是 25 档硬上限，换任何写法都躲不掉。
 * ----------------------------------------------------------
 * ★★★ 第八十四批新增（用户：「做一个新物品，材质用 saveditems/ba.yml，
 *     名字用 Bad Apple，右键为该玩家播放 Bad Apple!!!.nbs，冷却就是整首歌」）。
 *   · 物品：items.yml 的 GS_BAD_APPLE
 *           （**构思玩具第 11 格** —— 第 9 格是「海水过滤器」那台机器，
 *             它写在 recipe_machines.yml 里；第 10 格是「借寿」）
 *   · 配方：魔法工作台九宫格，**只有正中间第 5 格**放 1 个原版苹果
 *   · 材质：material_type: saveditem → saveditems/ba.yml
 *           （兔子皮 minecraft:rabbit_hide + item_model 渲染成附魔金苹果）
 *   · 与「咒术回战」是**同一套播放引擎**（都由 _check/nbs_to_js.py 生成），
 *     区别：本曲**不召唤任何生物**（CFG 里 mobs = null）
 *   · ★ 本曲比《雨爱》高潮部分长得多：183.5 秒 / 36462 个事件
 *     ⇒ 播放链是**每刻一步**的自调度（不是每个音符排一个任务），
 *       所以 3600 多刻也只是 3600 多次排任务，不会堆爆调度器。
 * ========================================================== */

// ---------------- 参数 ----------------
var SG_ITEM_ID     = 'GS_BAD_APPLE';
var SG_VOL         = 0.70;    // 总音量（所有音符统一乘这个数，想调大小改这里）
var SG_CD_MS       = 0;       // ★ 冷却（毫秒）—— 下面拿到曲长后自动 = SG_LEN_MS
var SG_DEBOUNCE_MS = 500;     // 去抖：一次右键可能连发两个事件，0.5 秒内只算一次
var SG_CD_HINT     = false;   // true = 冷却中在物品栏上方提示还剩几秒（默认静默）
