var SG_N      = SG_TL.length / 3;         // 音符总数
var SG_LEN_MS = SG_TL[SG_TL.length - 3];  // 全曲时长（毫秒）

// ★★ 用户要求：**冷却就是这首歌的时长** —— 曲长是算出来的，所以直接赋值，
//    以后换曲子 / 改速度都不用再手改冷却。
SG_CD_MS = SG_LEN_MS;

// 25 档音符盒音高（与游戏内 2^((n-12)/12) 完全一致）
var SG_PITCH = [];
(function () {
    for (var i = 0; i < 25; i++) SG_PITCH.push(Math.pow(2, (i - 12) / 12));
})();

// 加载标记：后台看到这行，说明「脚本 + 曲谱」都读进来了
//  ★★ 第五十四批：顺带把**排任务的函数在不在**报出来 ——
//     上次「排任务失败」排查了半天的教训：把结论直接写进启动日志，
//     下次一眼就能看出是环境问题还是逻辑问题。
try {
    var sgSchedOk = false;
    try { sgSchedOk = (typeof runLater === 'function'); } catch (e) { sgSchedOk = false; }
    getServer().getLogger().info('%s 已加载 · %s '
        + SG_N + ' 个音符 / ' + (SG_LEN_MS / 1000).toFixed(1) + ' 秒 · 冷却 '
        + (SG_CD_MS / 1000).toFixed(1) + ' 秒 · '
        + SG_SND.length + ' 种音效 · 排任务方式=' + (sgSchedOk ? 'runLater' : '调度器退路')
        );
} catch (e) { }

// ---------------- 冷却（按玩家记） ----------------
var SG_LAST = {};     // uuid -> 上次**起播**的时间戳(ms) —— 本曲时长的冷却
var SG_TOUCH = {};    // uuid -> 上次**按下去**的时间戳(ms) —— 去抖

function sgNow() {
    try { return Java.type('java.time.Instant').now().toEpochMilli(); }
    catch (e) { try { return new Date().getTime(); } catch (e2) { return 0; } }
}

// ★ 冷却：只在「起播」时记时 ⇒ 冷却正好等于曲长，曲子放完的那一刻就能再播
//   ★ 第五十五批：「再按一次就停」已删除 ⇒ 播放中再按只会被冷却挡住（静默忽略）
function sgCooldownLeft(p) {
    try {
        if (SG_CD_MS <= 0) return 0;
        var v = SG_LAST['' + p.getUniqueId()];
        if (v == null) return 0;
        var left = (0 + v) + SG_CD_MS - sgNow();
        return left > 0 ? left : 0;
    } catch (e) { return 0; }
}

function sgMarkUsed(p) {
    try { SG_LAST['' + p.getUniqueId()] = sgNow(); } catch (e) { }
}

// ★ 去抖：一次右键可能连发两个事件（Slimefun 的主手/副手各一个），
//   只认第一次 ⇒ 不然「按一下」会被当成「按两下」（开了又立刻关）
function sgDebounced(p) {
    try {
        if (SG_DEBOUNCE_MS <= 0) return false;
        var uuid = '' + p.getUniqueId();
        var v = SG_TOUCH[uuid];
        var now = sgNow();
        if (v != null && (0 + v) + SG_DEBOUNCE_MS > now) return true;
        SG_TOUCH[uuid] = now;
        return false;
    } catch (e) { return false; }
}

// 冷却提示（默认关掉，SG_CD_HINT = true 才用）
function sgCooldownHint(p, left) {
    try {
        if (!SG_CD_HINT) return;
        var s = Math.ceil(left / 1000);
        var C = null;
        try { C = Java.type('net.md_5.bungee.api.ChatColor'); } catch (e) { C = null; }
        var msg = (C != null ? ('' + C.GOLD) : '') + 'Bad Apple · 冷却中，还剩 '
                + s + ' 秒';
        try { p.sendActionBar(msg); }
        catch (e2) { try { p.sendMessage(msg); } catch (e3) { } }
    } catch (e) { }
}

// ---------------- 判定「手里拿的是不是本物品」 ----------------
function sgIsOurItem(stack) {
    try {
        if (stack == null) return false;
        // ① RSC 的判定（最准）
        try {
            var sf = getSfItemByItem(stack);
            if (sf != null && ('' + sf.getId()) === SG_ITEM_ID) return true;
        } catch (e) { }
        // ② Slimefun 标准 API 兜底
        try {
            var SFI = Java.type('io.github.thebusybiscuit.slimefun4.api.items.SlimefunItem');
            var sf2 = SFI.getByItem(stack);
            if (sf2 != null && ('' + sf2.getId()) === SG_ITEM_ID) return true;
        } catch (e) { }
        return false;
    } catch (e) { return false; }
}

// ---------------- 判定「这次触发算不算数」（只认主手） ----------------
function sgIsMainHandUse(event, p) {
    try {
        var slot = '';
        try { slot = '' + event.getHand().name(); } catch (e) { slot = ''; }
        if (slot.length === 0) {
            try { slot = '' + event.getInteractEvent().getHand().name(); } catch (e2) { slot = ''; }
        }
        if (slot.indexOf('OFF') >= 0) return false;

        var hand = null;
        try { hand = p.getInventory().getItemInMainHand(); } catch (e) { hand = null; }
        return sgIsOurItem(hand);
    } catch (e) { return false; }
}

// ---------------- 拦截：手持本物品右键方块 → 方块交互一律取消 ----------------
var SG_GUARD_OK = false;

function sgRegisterGuard() {
    if (SG_GUARD_OK) return true;
    try {
        var pm = getServer().getPluginManager();
        var Priority = Java.type('org.bukkit.event.EventPriority');

        var plugin = sgPlugin();
        if (plugin == null) return false;

        var InteractEv = null;
        try { InteractEv = Java.type('org.bukkit.event.player.PlayerInteractEvent'); } catch (e) { InteractEv = null; }
        if (InteractEv == null) return false;

        function handler(e) {
            try {
                var act = '';
                try { act = '' + e.getAction().name(); } catch (e2) { act = ''; }
                if (act.indexOf('RIGHT_CLICK') < 0) return;    // 只拦右键（左键留给玩家正常挖方块）

                // ★ 只认主手
                var hs = '';
                try { hs = '' + e.getHand().name(); } catch (e2) { hs = ''; }
                if (hs.length > 0 && hs.indexOf('OFF') >= 0) return;

                var h = null;
                try { h = e.getItem(); } catch (e2) { h = null; }
                if (h == null) return;
                if (!sgIsOurItem(h)) return;

                e.setCancelled(true);      // 方块功能不触发（箱子/耕地/按钮/放置…全拦）
            } catch (err) { }
        }

        try {
            pm.registerEvent(InteractEv, plugin, Priority.HIGHEST,
                function (l, e) { handler(e); }, plugin);
            SG_GUARD_OK = true;
        } catch (e1) {
            try {
                var ListenerC = Java.type('org.bukkit.event.Listener');
                var ExecC = Java.type('org.bukkit.plugin.EventExecutor');
                var listener = new JavaAdapter(ListenerC, {});
                var exec = new JavaAdapter(ExecC, { execute: function (l, e) { handler(e); } });
                pm.registerEvent(InteractEv, listener, Priority.HIGHEST, exec, plugin);
                SG_GUARD_OK = true;
            } catch (e2) { SG_GUARD_OK = false; }
        }
        return SG_GUARD_OK;
    } catch (e) { return false; }
}

// ==========================================================
//  播放引擎
// ----------------------------------------------------------
//  ★ 为什么不用「给每个音符排一个 runTaskLater」：
//    本曲有 36462 个音符，那样要排 36462 个任务；而且 runTaskLater 的延迟是
//    **按刻算的**（1 刻 = 50ms），本曲 1 个 NBS tick = 27.58ms ⇒ 会越播越偏。
//  ★ 这里的做法：**每刻一步的自调度链**，用系统毫秒减去起播时刻，
//    把「到点了还没放」的音符一次性全放掉 ⇒ **不会累积漂移**；
//    服务器卡一下也只是把攒下的音符一起补放，不会越拖越乱。
//
//  ★★★ 第五十四批修正（用户实测：日志说『排任务失败』、右键完全没声音）：
//    **不要用 getServer().getScheduler().runTaskTimer(plugin, jsFunction, 1, 1)**。
//    原因是 BukkitScheduler 上同时挂着两个重载：
//        runTaskTimer(Plugin, Runnable,            long, long) : BukkitTask
//        runTaskTimer(Plugin, Consumer<BukkitTask>, long, long) : void
//    GraalJS 拿一个 JS 函数去选，**分不清该转成哪一个** ⇒ 抛异常。
//    ⇒ 改用**本附属其它 13 处心跳一直在用**的 RSC 注入函数 `runLater(fn, delay)`
//      （它内部把 fn 固定成 java.util.function.Function，没有重载歧义）。
//  ★ `runLater` 排出去的任务**拿不到句柄、cancel 不掉**（本附属技能库里记着这条），
//    所以停播靠**世代号**：链上每一步先看自己的 gen 还等不等于表里的 gen，
//    不等就**不再排下一步** ⇒ 链自己断掉。
//  ★★ 世代号用**只增不减的全局计数器 SG_GEN**，绝不复位 ——
//    若按「表里旧值 +1」算，停掉再开很容易又得到同一个号，
//    旧链在途的那一步就会**认成自己还活着** ⇒ 两条链同时播（声音重叠、还停不掉）。
// ==========================================================
var SG_PLAY = {};     // uuid -> { p, start, i, gen }
var SG_GEN  = 0;      // ★ 全局单调递增的世代号（永不复位）

// 拿插件实例（只在 runLater 不可用的退路里才用得到）
function sgPlugin() {
    try {
        var pm = getServer().getPluginManager();
        var pl = null;
        try { pl = pm.getPlugin('RykenSlimeCustomizer'); } catch (e) { pl = null; }
        if (pl == null) {
            try { pl = Java.type('org.lins.mmmjjkx.rykenslimefuncustomizer.RykenSlimefunCustomizer').INSTANCE; }
            catch (e) { }
        }
        if (pl == null) { try { pl = pm.getPlugin('Slimefun'); } catch (e) { } }
        return pl;
    } catch (e) { return null; }
}

// 停掉某个玩家正在播的歌（把世代号作废，链上在途的那一步会自终止）
function sgPlayStopUuid(uuid) {
    try {
        var st = SG_PLAY[uuid];
        if (st == null) return;
        st.gen = 0;              // 0 永远不等于任何真实世代号 ⇒ 旧链必断
        SG_PLAY[uuid] = null;
    } catch (e) { }
}

// 排一步（delay 刻之后执行 fn）。
//  ★★ 三条路依次试，**第一条是正路**，后面两条只是「别整个哑掉」的保险。
function sgSchedule(fn, delay) {
    // ① 正路：RSC 注入的 runLater（本附属 13 处心跳都在用，实测可用）
    try { runLater(fn, delay); return true; } catch (eRL) { }

    // ② 退路一：用 GraalJS 的 Java.extend **显式**造一个 Runnable。
    //    直接传 JS 函数给 runTaskLater 会撞上 Runnable/Consumer 重载歧义，
    //    显式造出 Runnable 就没有歧义了。
    try {
        var RC = Java.type('java.lang.Runnable');
        var Impl = Java.extend(RC, { run: function () { fn(); } });
        var rr = new Impl();
        var sched = getServer().getScheduler();
        var pl = sgPlugin();
        if (sched != null && pl != null) { sched.runTaskLater(pl, rr, delay); return true; }
    } catch (e1) { }

    // ③ 退路二：直接传函数（多半会因重载歧义失败，但试一下不要钱）
    try {
        var sched = getServer().getScheduler();
        var pl = sgPlugin();
        if (sched != null && pl != null) { sched.runTaskLater(pl, fn, delay); return true; }
    } catch (e2) {
        try { getServer().getLogger().warning('[构思技艺] Bad Apple 排任务失败: ' + e2); } catch (e3) { }
    }
    return false;
}

// 自调度链：每刻一步。被停掉（gen 变了）/ 退服 / 播完 ⇒ 断链
function sgPlayLoop(uuid, gen) {
    sgSchedule(function () {
        var st = null;
        try { st = SG_PLAY[uuid]; } catch (e0) { st = null; }
        if (st == null || st.gen !== gen) return;      // ★ 已被停掉 / 取代 ⇒ 断链
        var p = st.p;
        var ok = true;
        try { if (p == null || !p.isOnline()) ok = false; } catch (e1) { ok = false; }
        if (!ok) { sgPlayStopUuid(uuid); return; }      // 退服 ⇒ 收尾并断链
        sgPlayPulse(uuid);
        var st2 = null;
        try { st2 = SG_PLAY[uuid]; } catch (e2) { st2 = null; }
        if (st2 != null && st2.gen === gen) sgPlayLoop(uuid, gen);   // 没播完 ⇒ 排下一步
    }, 1);
}

// 起播（先把上一首停掉）
function sgPlayStart(p) {
    try {
        var uuid = '' + p.getUniqueId();
        sgPlayStopUuid(uuid);

        SG_GEN = SG_GEN + 1;                           // ★ 只增不减，绝不复位
        var gen = SG_GEN;
        SG_PLAY[uuid] = { p: p, start: sgNow(), i: 0, gen: gen };
        sgPlayLoop(uuid, gen);
        return true;
    } catch (e) {
        try { getServer().getLogger().warning('[构思技艺] Bad Apple 起播失败: ' + e); } catch (e2) { }
        return false;
    }
}

// 心跳：把「到点了」的音符全放掉（由 sgPlayLoop 每刻调一次）
function sgPlayPulse(uuid) {
    try {
        var st = SG_PLAY[uuid];
        if (st == null) return;                    // 已经被停掉了
        var p = st.p;
        if (p == null || !p.isOnline()) { sgPlayStopUuid(uuid); return; }   // 退服了

        var el  = sgNow() - st.start;              // 已经播了多少毫秒
        var loc = null;
        while (st.i < SG_N && SG_TL[st.i * 3] <= el) {
            var code = SG_TL[st.i * 3 + 1];
            var snd  = SG_SND[(code / 32) | 0];    // 高位 = 音效下标
            var vol  = SG_TL[st.i * 3 + 2];        // 0~100
            st.i++;
            if (snd == null) continue;

            var v = SG_VOL * (vol / 100);
            var g = SG_GAIN[snd];
            if (g != null) v = v * g;
            if (v <= 0) continue;

            if (loc == null) loc = p.getLocation();   // 跟着玩家走
            var pit = SG_PITCH[code % 32];
            try {
                if (SG_OWNER_ONLY) p.playSound(loc, snd, v, pit);
                else               p.getWorld().playSound(loc, snd, v, pit);
            } catch (e) { }
        }
        if (st.i >= SG_N) sgPlayStopUuid(uuid);    // 播完了
    } catch (e) { }
}

try {
    if (sgRegisterGuard()) {
        try { getServer().getLogger().info('[构思技艺] Bad Apple：方块交互拦截 已启用'); } catch (e) { }
    }
} catch (e) { }

// ---------------- 入口 ----------------
function onUse(event) {
    try {
        // 惰性重试：加载时插件可能还没就绪
        try { sgRegisterGuard(); } catch (e) { }

        var p = null;
        try { p = event.getPlayer(); } catch (e) { p = null; }
        if (p == null) return;

        // ★ 只认主手触发
        if (!sgIsMainHandUse(event, p)) return;

        // ★ 去抖（一次右键的两个事件只认一个）
        if (sgDebounced(p)) return;

        // 起播 ⇒ 走冷却（冷却中**静默忽略**，物品不消耗）
        // ★ 第五十五批：**取消了「再按一次就停」**（用户「再按停止的效果删除」）。
        //   冷却正好等于曲长 ⇒ 整首歌期间再按都落在这里、被静默忽略。
        var left = sgCooldownLeft(p);
        if (left > 0) { sgCooldownHint(p, left); return; }
        sgMarkUsed(p);

        sgPlayStart(p);
    } catch (err) {
        try { getServer().getLogger().warning('[构思技艺] Bad Apple onUse 出错: ' + err); } catch (e) { }
    }
}
